/** Export a consistent business snapshot; account credentials are deliberately excluded. */
export async function exportBackup(pool: Pool) {
  return transaction(pool, async db => {
    const result = await db.query<{ kind: Kind; data: Records[Kind] }>('SELECT kind,data FROM records ORDER BY kind,id');
    const records: { [K in Kind]: Records[K][] } = {
      customers: [], bikes: [], items: [], jobs: [], invoices: [], payments: [], expenses: [], movements: [], reminders: [],
    };
    for (const row of result.rows) {
      // Each database kind determines its corresponding validated record schema.
      (records[row.kind] as Records[Kind][]).push(row.data);
    }
    const sequence = await db.query<{ invoice_sequence: number }>('SELECT invoice_sequence FROM garage WHERE id=1');
    return { version: 1, exportedAt: new Date().toISOString(), settings: await settings(db),
      invoiceSequence: sequence.rows[0].invoice_sequence, records };
  });
}

/** Validate referential and accounting integrity before restoring into an empty garage. */
export async function restoreBackup(pool: Pool, input: unknown, actorId: string) {
  const backup = backupSchema.parse(input);
  const refs = Object.fromEntries(kinds.map(kind => [kind, new Set(backup.records[kind].map(row => row.id))])) as Record<Kind, Set<string>>;
  for (const kind of kinds) {
    if (refs[kind].size !== backup.records[kind].length) throw new DomainError(`Duplicate ${kind} IDs in backup`);
  }
  for (const vehicle of backup.records.bikes) {
    if (!refs.customers.has(vehicle.customerId)) throw new DomainError('Bike references a missing customer');
  }
  const jobInvoices = new Set<string>();
  const invoiceNumbers = new Set<string>();
  const vehicles = new Map(backup.records.bikes.map(value => [value.id, value]));
  const jobs = new Map(backup.records.jobs.map(value => [value.id, value]));
  const invoices = new Map(backup.records.invoices.map(value => [value.id, value]));
  const paid = new Map<string, number>();
  const timelineIds = new Set<string>();
  for (const value of backup.records.customers) {
    if (value.whatsappConsent !== Boolean(value.consentAt)) throw new DomainError('Customer consent and consent timestamp do not match');
  }
  for (const job of backup.records.jobs) {
    if (!refs.bikes.has(job.bikeId) || job.parts.some(line => !refs.items.has(line.itemId))) throw new DomainError('Job references missing bike or inventory');
    if (new Set(job.parts.map(line => line.itemId)).size !== job.parts.length) throw new DomainError('Job has duplicate parts');
    if (job.nextServiceDate && job.nextServiceDate <= job.serviceDate) throw new DomainError('Invalid next service date');
    if (job.timeline && (new Set(job.timeline.map(v => v.id)).size !== job.timeline.length ||
      (job.timeline.length > 0 && job.stage !== job.timeline[job.timeline.length - 1].stage))) {
      throw new DomainError('Invalid service tracking timeline');
    }
    if (['open', 'in_progress'].includes(job.status) && (job.timeline?.length || 0) > 198) {
      throw new DomainError('Open service must reserve timeline capacity for completion and delivery');
    }
    for (const event of job.timeline || []) {
      if (timelineIds.has(event.id)) throw new DomainError('Duplicate timeline event across services');
      timelineIds.add(event.id);
    }
  }
  for (const invoice of backup.records.invoices) {
    if (!refs.jobs.has(invoice.jobId) || !refs.customers.has(invoice.customerId) ||
      invoice.parts.some(line => !refs.items.has(line.itemId))) throw new DomainError('Invoice references missing records');
    const calculated = totals(invoice.parts, invoice.laborPaise, invoice.gstBasisPoints);
    if (Object.entries(calculated).some(([key, value]) => invoice[key as keyof typeof calculated] !== value)) throw new DomainError('Invoice totals do not match');
    const job = jobs.get(invoice.jobId)!;
    if (vehicles.get(job.bikeId)!.customerId !== invoice.customerId ||
      job.serviceDate !== invoice.date || job.laborPaise !== invoice.laborPaise ||
      job.gstBasisPoints !== invoice.gstBasisPoints || JSON.stringify(job.parts) !== JSON.stringify(invoice.parts)) {
      throw new DomainError('Invoice does not match its service job');
    }
    if (jobInvoices.has(invoice.jobId) || invoiceNumbers.has(invoice.number)) throw new DomainError('Duplicate job invoice or invoice number');
    if (Number(invoice.number.slice(3)) > backup.invoiceSequence) throw new DomainError('Invoice sequence is invalid');
    jobInvoices.add(invoice.jobId); invoiceNumbers.add(invoice.number);
  }
  for (const job of backup.records.jobs) {
    if ((job.status === 'completed') !== jobInvoices.has(job.id)) throw new DomainError('Job completion and invoice do not match');
  }
  for (const value of backup.records.payments) {
    if (!invoices.has(value.invoiceId)) throw new DomainError('Payment references missing invoice');
    paid.set(value.invoiceId, (paid.get(value.invoiceId) || 0) + value.amountPaise);
  }
  for (const [invoiceId, amount] of paid) {
    if (amount > invoices.get(invoiceId)!.totalPaise) throw new DomainError('Backup has overpaid invoice');
  }
  const stockBalances = new Map<string, number>();
  for (const value of backup.records.movements) {
    if (!refs.items.has(value.itemId)) throw new DomainError('Movement references missing inventory');
    stockBalances.set(value.itemId, (stockBalances.get(value.itemId) || 0) + value.delta);
  }
  for (const value of backup.records.items) {
    if ((stockBalances.get(value.id) || 0) !== value.quantity) throw new DomainError('Inventory does not match stock movement history');
  }
  const remindedJobs = new Set<string>();
  for (const value of backup.records.reminders) {
    if (!refs.jobs.has(value.jobId)) throw new DomainError('Reminder references missing job');
    const job = jobs.get(value.jobId)!;
    if (value.purpose === 'service_status') {
      const event = job.timeline?.find(v => v.id === value.eventId);
      if (!event || value.id !== event.id || value.stage !== event.stage || value.note !== event.note) {
        throw new DomainError('Status message does not match its timeline event');
      }
      continue;
    }
    if (job.status !== 'completed' || job.nextServiceDate !== value.dueDate || remindedJobs.has(value.jobId)) {
      throw new DomainError('Reminder does not match its completed service job');
    }
    remindedJobs.add(value.jobId);
  }
  if (new Set(backup.records.items.map(v => v.sku.toLowerCase())).size !== backup.records.items.length ||
      new Set(backup.records.bikes.map(v => v.registration)).size !== backup.records.bikes.length) {
    throw new DomainError('Duplicate SKU or bike registration');
  }
  return transaction(pool, async db => {
    const existing = await db.query<{ total: string }>('SELECT COUNT(*) AS total FROM records');
    if (Number(existing.rows[0].total)) throw new DomainError('Restore requires an empty garage; use a separate database to avoid overwriting live data', 409);
    const staff = await db.query<{ id: string }>('SELECT id FROM users WHERE active=TRUE');
    const staffIds = new Set(staff.rows.map(row => row.id));
    for (const kind of kinds) {
      for (const row of backup.records[kind]) {
        let restored: Records[Kind] = row;
        if (kind === 'jobs') {
          const job = row as Records['jobs'];
          restored = { ...job, assignedTo: job.assignedTo && staffIds.has(job.assignedTo) ? job.assignedTo : undefined };
        } else if (kind === 'reminders' && (row as Records['reminders']).status === 'sending') {
          restored = { ...(row as Records['reminders']), status: 'pending' };
        }
        await save(db, kind, restored);
      }
    }
    await db.query('UPDATE garage SET settings=$1,invoice_sequence=$2 WHERE id=1', [backup.settings, backup.invoiceSequence]);
    await audit(db, actorId, 'business.restore');
    return { restored: Object.values(backup.records).reduce((sum, rows) => sum + rows.length, 0) };
  });
}
